import{_ as e,o as t,c as o,a2 as s}from"./chunks/framework.DCVnL8g5.js";const m=JSON.parse('{"title":"Introducción y arquitectura","description":"","frontmatter":{},"headers":[],"relativePath":"data-engineering/delta-lake/01-introduccion-y-arquitectura.md","filePath":"data-engineering/delta-lake/01-introduccion-y-arquitectura.md","lastUpdated":1789040978000,"isDraft":false}'),r={name:"data-engineering/delta-lake/01-introduccion-y-arquitectura.md"};function n(l,a,i,c,d,p){return t(),o("div",null,[...a[0]||(a[0]=[s(`<h1 id="introduccion-y-arquitectura" tabindex="-1">Introducción y arquitectura <a class="header-anchor" href="#introduccion-y-arquitectura" aria-label="Permalink to &quot;Introducción y arquitectura&quot;">​</a></h1><p>Delta Lake es un <strong>formato y protocolo de tabla</strong> de código abierto: archivos de datos (casi siempre <a href="https://parquet.apache.org/" target="_blank" rel="noreferrer">Parquet</a>) más un <strong>transaction log</strong> que define el estado versionado de la tabla. Encima de un data lake (S3, ADLS, GCS, HDFS u otro almacenamiento de objetos/ficheros) añade transacciones ACID, snapshots, enforcement de esquema y un mismo dataset para batch y streaming.</p><p>Documentación: <a href="https://docs.delta.io/" target="_blank" rel="noreferrer">docs.delta.io</a>, <a href="https://github.com/delta-io/delta" target="_blank" rel="noreferrer">repositorio delta-io/delta</a>, <a href="https://docs.delta.io/latest/quick-start.html" target="_blank" rel="noreferrer">guía rápida</a>.</p><h2 id="el-problema-del-data-lake-solo-ficheros" tabindex="-1">El problema del data lake “solo ficheros” <a class="header-anchor" href="#el-problema-del-data-lake-solo-ficheros" aria-label="Permalink to &quot;El problema del data lake “solo ficheros”&quot;">​</a></h2><p>Un lago clásico deja directorios de Parquet (o JSON/CSV) y delega la consistencia al job:</p><ul><li>un escritor que pisa ficheros a medias deja lecturas a medio camino;</li><li>dos jobs que escriben el mismo path no tienen un commit atómico compartido;</li><li>no hay un “estado de tabla” único: el lector lista lo que hay en el directorio;</li><li><code>UPDATE</code>/<code>DELETE</code>/<code>MERGE</code> no existen como operación de tabla: reescribes particiones a mano.</li></ul><p>Delta no sustituye el lago. Añade un <strong>protocolo</strong> sobre esos ficheros para que varios lectores y escritores hablen de la misma tabla.</p><h2 id="que-no-es-delta-lake" tabindex="-1">Qué no es Delta Lake <a class="header-anchor" href="#que-no-es-delta-lake" aria-label="Permalink to &quot;Qué no es Delta Lake&quot;">​</a></h2><table tabindex="0"><thead><tr><th>No es</th><th>Por qué</th></tr></thead><tbody><tr><td>Una base de datos separada</td><td>No hay un servidor de filas propio. Los datos viven en el storage; el motor (Spark, Flink, Trino, …) interpreta el protocolo.</td></tr><tr><td>Un formato que reemplaza Parquet en disco</td><td>Los data files siguen siendo Parquet (u otro formato que el protocolo permita). El log es lo que convierte el directorio en tabla.</td></tr><tr><td>Un motor de consultas</td><td>No ejecuta SQL por sí mismo. Spark SQL, Trino u otro motor leen el snapshot.</td></tr><tr><td>Databricks</td><td>Databricks <strong>usa</strong> Delta y añade producto (Runtime, SQL warehouse, Unity Catalog, Predictive Optimization). Este manual cubre <strong>Delta Lake OSS</strong>.</td></tr></tbody></table><p>Apache Iceberg es otro formato/protocolo de tabla lakehouse, con su propio manifiesto y catálogo. Comparten el problema (tablas ACID sobre un lago); no son el mismo diseño. Iceberg se trata en su manual.</p><p><strong>Bronze / Silver / Gold</strong> es un patrón de capas (muy usado en lakehouses). No es un requisito del formato Delta.</p><h2 id="arquitectura-parquet-delta-log" tabindex="-1">Arquitectura: Parquet + <code>_delta_log</code> <a class="header-anchor" href="#arquitectura-parquet-delta-log" aria-label="Permalink to &quot;Arquitectura: Parquet + \`_delta_log\`&quot;">​</a></h2><p>Una tabla path-based es un directorio:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/events/</span></span>
<span class="line"><span>├── part-00000-….parquet</span></span>
<span class="line"><span>├── part-00001-….parquet</span></span>
<span class="line"><span>└── _delta_log/</span></span>
<span class="line"><span>    ├── 00000000000000000000.json</span></span>
<span class="line"><span>    ├── 00000000000000000001.json</span></span>
<span class="line"><span>    ├── …</span></span>
<span class="line"><span>    └── 00000000000000000010.checkpoint.parquet</span></span></code></pre></div><ul><li>Los <code>part-*.parquet</code> son <strong>data files</strong>. Un commit puede añadir ficheros, marcar otros como eliminados del snapshot, o ambas cosas. Los ficheros antiguos no se borran del storage hasta un <code>VACUUM</code>.</li><li><code>_delta_log/</code> es el <strong>transaction log</strong>: commits JSON numerados (versión 0, 1, 2, …) y, periódicamente, <strong>checkpoints</strong> (Parquet) que compactan el historial para no releer miles de JSON.</li></ul><p>El snapshot <em>N</em> es el estado de la tabla <strong>después</strong> del commit <code>N</code>: qué ficheros están activos, esquema, propiedades y particionado. Un lector elige un snapshot y no ve escrituras posteriores a mitad de su job.</p><p><code>_delta_log</code> es protocolo interno. Puedes <strong>listarlo</strong> para entender el modelo. No edites JSON, no borres commits y no “arregles” la tabla tocando ficheros a mano.</p><h2 id="garantias-que-introduce-el-log" tabindex="-1">Garantías que introduce el log <a class="header-anchor" href="#garantias-que-introduce-el-log" aria-label="Permalink to &quot;Garantías que introduce el log&quot;">​</a></h2><ul><li><strong>ACID</strong> entre lecturas y escrituras que respetan el protocolo (capítulo 3).</li><li><strong>Snapshots / time travel</strong>: cada commit es una versión (capítulo 5).</li><li><strong>Schema enforcement</strong>: un append incompatible falla en lugar de mezclar columnas a ciegas (capítulo 2).</li><li><strong>DML</strong>: <code>UPDATE</code>, <code>DELETE</code>, <code>MERGE</code> reescriben ficheros afectados y commitean un snapshot nuevo (capítulo 4).</li><li><strong>Batch y streaming</strong> sobre la misma tabla (capítulo 7).</li></ul><h2 id="lakehouse-a-alto-nivel" tabindex="-1">Lakehouse, a alto nivel <a class="header-anchor" href="#lakehouse-a-alto-nivel" aria-label="Permalink to &quot;Lakehouse, a alto nivel&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>object store (S3 / ADLS / GCS / HDFS)</span></span>
<span class="line"><span>        ↑</span></span>
<span class="line"><span>   Delta table = data files + _delta_log</span></span>
<span class="line"><span>        ↑</span></span>
<span class="line"><span> motor (Spark, Flink, Trino, Kernel, …)</span></span>
<span class="line"><span>        ↑</span></span>
<span class="line"><span>  batch · streaming · SQL</span></span></code></pre></div><p>El storage guarda bytes. Delta define <strong>qué conjunto de ficheros es la tabla ahora</strong>. El motor planifica lecturas y writes. Un <strong>catálogo</strong> (Hive metastore, Unity Catalog OSS, otro) es opcional: puedes trabajar solo con la ruta <code>/data/events</code>. El catálogo no es Databricks.</p><p><strong>Delta Kernel</strong> es una librería para construir conectores que lean y escriban Delta sin reimplementar el protocolo a mano. Spark sigue siendo el motor pedagógico de este manual; no todas las features tienen el mismo soporte en todos los motores.</p><h2 id="oss-frente-a-databricks" tabindex="-1">OSS frente a Databricks <a class="header-anchor" href="#oss-frente-a-databricks" aria-label="Permalink to &quot;OSS frente a Databricks&quot;">​</a></h2><p>En los capítulos siguientes, lo que aparece como API de <a href="https://docs.delta.io/" target="_blank" rel="noreferrer">docs.delta.io</a> es <strong>Delta Lake OSS</strong> (Spark, SQL, <code>delta.tables</code>). No se presentan como universales:</p><ul><li>Databricks Runtime / Databricks SQL</li><li>Unity Catalog (producto Databricks; existe un Unity Catalog OSS aparte)</li><li>Predictive Optimization, Auto Optimize como producto</li><li>Liquid Clustering automático gestionado por la plataforma</li></ul><p>Si una capacidad existe en OSS <strong>y</strong> en Databricks con semántica distinta, se etiqueta. Si solo está en producto Databricks, no se enseña como receta del formato.</p><h2 id="versiones" tabindex="-1">Versiones <a class="header-anchor" href="#versiones" aria-label="Permalink to &quot;Versiones&quot;">​</a></h2><p>La guía rápida de docs.delta.io a veces muestra un artefacto concreto (por ejemplo 4.0.0). Eso <strong>no</strong> es necesariamente la release estable actual. Comprueba <a href="https://github.com/delta-io/delta/releases" target="_blank" rel="noreferrer">releases de delta-io/delta</a> y la matriz Spark/Scala de esa nota. En Spark 4.x los artefactos van versionados por línea de Spark (<code>delta-spark_4.2_2.13</code>, etc.). Este manual no fija una versión en cada ejemplo.</p><p>Siguiente: <a href="./02-tablas-delta">Tablas Delta</a>.</p>`,30)])])}const g=e(r,[["render",n]]);export{m as __pageData,g as default};
